[归一化后的问题]
2026-08 的日期维表有多少天？

[已审查的查询计划]
{
  "assets": [
    {
      "asset": "dim_date",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "dim_date.date_key 落在 2026-08-01 至 2026-08-31 之间（月份筛选谓词须显式给出，day_cnt 默认不带时间谓词）"
  ],
  "grain": "day（日历维表存量天数，按 date_key 计数）",
  "limit": 100,
  "metrics": [
    {
      "caliber": "day_cnt（天数）：日历维表 v_dim_date 的存量天数，COUNT(*)，单位=天；须显式加月份筛选谓词，本指标默认不带任何时间谓词。",
      "name": "day_cnt"
    }
  ],
  "order_by": [],
  "output_columns": [
    "day_cnt"
  ],
  "time_range": {
    "end": "2026-08-31",
    "start": "2026-08-01"
  }
}

